  };

  sink.flush = async (): Promise<void> => {
    if (flushTimer) {
      clearTimeout(flushTimer);
      flushTimer = null;
    }
    await flushBuffer();
  };

  sink.close = (): Promise<void> => {
    if (closed) return Promise.resolve();
    if (closing) return closing;
    closing = (async () => {
      await sink.flush!();
